"""A collection of classes used in the 'machine code' generated by Auto Maple's compiler for each routine."""

import csv
import os
import threading
from os.path import splitext, basename
from src.common import config, settings, utils
from src.routine.components import Point, Label, Jump, Setting, Command, SYMBOLS
from src.routine.layout import Layout


def _refresh_gui(routine):
    """Asks the GUI (if any) to redraw the routine and the details panel."""

    gui = config.gui
    if gui is None:
        return
    utils.gui_call(gui.set_routine, list(routine.display))
    utils.gui_call(gui.view.details.update_details)


def update(func):
    """
    Decorator function that keeps Labels/Jumps linked and updates both the displayed
    routine and details for all mutative Routine operations.
    """

    def f(self, *args, **kwargs):
        with self.lock:
            result = func(self, *args, **kwargs)
            self.relink()
        _refresh_gui(self)
        return result
    return f


def mark_dirty(func):
    """Decorator function that sets the dirty bit for mutative Routine operations."""

    def f(self, *args, **kwargs):
        result = func(self, *args, **kwargs)
        self.dirty = True
        return result
    return f


class Routine:
    """Describes a routine file in Auto Maple's custom 'machine code'."""

    def __init__(self):
        self.lock = threading.RLock()       # Shared by the bot thread and the GUI
        self._dirty = False
        self.path = ''
        self.labels = {}
        self.index = 0
        self.sequence = []
        self.display = []       # Updated alongside sequence

    @property
    def dirty(self):
        return self._dirty

    @dirty.setter
    def dirty(self, value):
        changed = self._dirty != value
        self._dirty = value
        update_title = getattr(config.gui, 'update_title', None)
        if changed and update_title is not None:
            utils.gui_call(update_title)

    def relink(self):
        """
        Rebuilds the Label table from the current sequence, refreshes every Label's index,
        binds every Jump to its Label, and keeps the execution index in range.
        """

        with self.lock:
            labels = {}
            for i, c in enumerate(self.sequence):
                if isinstance(c, Label):
                    c.set_index(i)
                    labels[c.label] = c
            self.labels = labels
            for c in self.sequence:
                if isinstance(c, Jump):
                    c.bind(labels)
            if self.index >= len(self.sequence) or self.index < 0:
                self.index = 0

    def _check_new_label(self, obj):
        if isinstance(obj, Label) and obj.label in self.labels:
            raise ValueError(f"Label '{obj.label}' already exists.")

    @mark_dirty
    @update
    def set(self, arr):
        self.sequence = arr
        self.display = [str(x) for x in arr]

    @mark_dirty
    @update
    def append_component(self, p):
        self._check_new_label(p)
        self.sequence.append(p)
        self.display.append(str(p))

    @mark_dirty
    @update
    def append_command(self, i, c):
        """Appends Command object C to the Point at index I in the sequence."""

        target = self.sequence[i]
        target.commands.append(c)
        self.display[i] = str(target)

    def _swap(self, a, b):
        self.sequence[a], self.sequence[b] = self.sequence[b], self.sequence[a]
        self.display[a], self.display[b] = self.display[b], self.display[a]
        if self.index == a:
            self.index = b
        elif self.index == b:
            self.index = a

    @mark_dirty
    @update
    def move_component_up(self, i):
        """Moves the component at index I upward if possible."""

        if i > 0:
            self._swap(i, i - 1)
            return i - 1
        return i

    @mark_dirty
    @update
    def move_component_down(self, i):
        if i < len(self.sequence) - 1:
            self._swap(i, i + 1)
            return i + 1
        return i

    @mark_dirty
    @update
    def move_command_up(self, i, j):
        """
        Within the Point at routine index I, moves the Command at index J upward
        if possible and updates the Edit UI.
        """

        point = self.sequence[i]
        if j > 0:
            point.commands[j-1], point.commands[j] = point.commands[j], point.commands[j-1]
            return j - 1
        return j

    @mark_dirty
    @update
    def move_command_down(self, i, j):
        point = self.sequence[i]
        if j < len(point.commands) - 1:
            point.commands[j+1], point.commands[j] = point.commands[j], point.commands[j+1]
            return j + 1
        return j

    @mark_dirty
    @update
    def delete_component(self, i):
        """Deletes the Component at index I and keeps the execution index on the same element."""

        self.sequence.pop(i)
        self.display.pop(i)
        if i < self.index:
            self.index -= 1

    @mark_dirty
    @update
    def delete_command(self, i, j):
        """Within the Point at routine index I, deletes the Command at index J."""

        point = self.sequence[i]
        point.commands.pop(j)
        self.display[i] = str(point)

    @update
    def update_component(self, i, new_kwargs):
        """Returns True if the Component was updated, otherwise reports the reason and returns False."""

        target = self.sequence[i]
        try:
            if isinstance(target, Label):
                new_label = str(new_kwargs.get('label', target.label))
                if new_label != target.label and new_label in self.labels:
                    raise ValueError(f"Label '{new_label}' already exists.")
            target.update(**new_kwargs)
            self.display[i] = str(target)
            self.dirty = True
            return True
        except (ValueError, TypeError) as e:
            utils.report_error(f"Invalid arguments for '{target.__class__.__name__}': {e}")
            return False

    @update
    def update_command(self, i, j, new_kwargs):
        """Returns True if the Command was updated, otherwise reports the reason and returns False."""

        target = self.sequence[i].commands[j]
        try:
            target.update(**new_kwargs)
            self.display[i] = str(self.sequence[i])
            self.dirty = True
            return True
        except (ValueError, TypeError) as e:
            utils.report_error(f"Invalid arguments for '{target.__class__.__name__}': {e}")
            return False

    @utils.run_if_enabled
    def step(self):
        """Increments the execution index and wraps back to 0 at the end of the sequence."""

        with self.lock:
            if self.sequence:
                self.index = (self.index + 1) % len(self.sequence)

    def current(self):
        """Returns the Component at the execution index, or None if the routine is empty."""

        with self.lock:
            if not self.sequence:
                return None
            if self.index >= len(self.sequence):
                self.index = 0
            return self.sequence[self.index]

    def encode(self):
        """Returns the routine encoded as the text of a routine file."""

        result = []
        for item in self.sequence:
            result.append(item.encode())
            if isinstance(item, Point):
                for c in item.commands:
                    result.append(' ' * 4 + c.encode())
        result.append('')
        return '\n'.join(result)

    def save(self, file_path):
        """Encodes and atomically saves the current Routine at location FILE_PATH."""

        text = self.encode()
        tmp_path = file_path + '.tmp'
        with open(tmp_path, 'w', encoding='utf-8', newline='') as file:
            file.write(text)
        os.replace(tmp_path, file_path)        # Never leaves a half-written routine behind
        self.path = file_path
        self.dirty = False

        utils.print_separator()
        utils.report_info(f"Saved routine to '{basename(file_path)}'.")

    def clear(self):
        self.index = 0
        self.set([])
        self.dirty = False
        self.path = ''
        config.layout = None
        settings.reset()

        if config.gui is not None:
            utils.gui_call(config.gui.clear_routine_info)

    def load(self, file=None):
        """
        Attempts to load FILE into a sequence of Components. If no file path is provided, attempts to
        load the previous routine file.
        :param file:    The file's path.
        :return:        True if the routine was loaded, otherwise False.
        """

        utils.print_separator()
        if not file:
            if self.path:
                file = self.path
                print(' *  File path not provided, using previously loaded routine')
            else:
                utils.report_error('No routine file provided and no routine was previously loaded.')
                return False
        print(f"[~] Loading routine '{basename(file)}':")

        ext = splitext(file)[1]
        if ext != '.csv':
            utils.report_error(f"'{ext}' is not a supported routine file extension.")
            return False

        self.clear()

        # Compile and Link
        errors = self.compile(file)
        self.relink()
        for c in self.sequence:
            if isinstance(c, Jump) and c.link is None:
                errors += 1
                print(f" !  Jump to label '{c.label}' has no matching label.")

        self.dirty = False
        self.path = file
        config.layout = Layout.load(file)
        if config.gui is not None:
            utils.gui_call(config.gui.view.status.set_routine, basename(file))
            utils.gui_call(config.gui.edit.minimap.draw_default)
        name = basename(splitext(file)[0])
        if errors:
            utils.report_error(f"Loaded routine '{name}' with {errors} error(s), see console for details.")
        else:
            utils.report_info(f"Finished loading routine '{name}'.")
        return True

    def compile(self, file):
        """Compiles FILE into this routine. Returns the number of lines that had errors."""

        self.labels = {}
        errors = 0
        with open(file, newline='') as f:
            csv_reader = csv.reader(f, skipinitialspace=True)
            curr_point = None
            line = 1
            for row in csv_reader:
                result, ok = self._eval(row, line)
                if not ok:
                    errors += 1
                if result:
                    if isinstance(result, Command):
                        if curr_point:
                            curr_point.commands.append(result)
                        else:
                            errors += 1
                            print(f" !  Line {line}: Command '{result.id}' appears before any Point "
                                  f"and was ignored.")
                    else:
                        self.append_component(result)
                        if isinstance(result, Point):
                            curr_point = result
                line += 1
        return errors

    def _eval(self, row, i):
        """Returns (component or None, whether the row was valid)."""

        if not row or not isinstance(row, list) or not row[0].strip():
            return None, True
        first, rest = row[0].strip().lower(), row[1:]
        args, kwargs = utils.separate_args(rest)
        line_error = f' !  Line {i}: '

        if first in SYMBOLS:
            c = SYMBOLS[first]
        elif config.bot is not None and config.bot.command_book is not None \
                and first in config.bot.command_book:
            c = config.bot.command_book[first]
        else:
            print(line_error + f"Command '{first}' does not exist.")
            return None, False

        try:
            obj = c(*args, **kwargs)
            self._check_new_label(obj)
            return obj, True
        except (ValueError, TypeError) as e:
            print(line_error + f"Found invalid arguments for '{c.__name__}':")
            print(f"{' ' * 4} -  {e}")
            return None, False

    @staticmethod
    def get_all_components():
        """Returns a dictionary mapping all creatable Components to their names."""

        options = config.bot.command_book.dict.copy()
        for e in (Point, Label, Jump, Setting):
            options[e.__name__.lower()] = e
        return options

    def __getitem__(self, i):
        return self.sequence[i]

    def __len__(self):
        return len(self.sequence)
